import json,glob
def walk(n,d,out):
    out.append("  "*d+"- "+n["name"])
    for c in n.get("children",[]): walk(c,d+1,out)
for f in glob.glob("Chapter*/*.json"):
    out=[]; walk(json.load(open(f,encoding="utf-8")),0,out)
    open(f[:-5]+".md","w",encoding="utf-8").write("\n".join(out)+"\n")
    print(f[:-5]+".md")
EOF

